const fs = require('node:fs');
const path = require('node:path');
const { spawnSync } = require('node:child_process');
const files = {
  'pageObjects/OpenAccountPage.js': `export class OpenAccountPage {
    constructor(page) {
        this.openNewAccountLink = page.getByRole('link', { name: 'Open New Account', exact: true });
        this.accountType = page.locator('#type');
        this.openAccountButton = page.getByRole('button', { name: 'Open New Account', exact: true });
        this.openedAccountNumber = page.locator('#newAccountId');
    }

    async clickOpenNewAccountLink() {
        await this.openNewAccountLink.click();
    }

    async openNewAccount(accountType = 'CHECKING') {
        await this.accountType.selectOption({ label: accountType });
        await this.openAccountButton.click();
    }
}
`,
  'tests/tcopenaccount.spec.js': `import { POManager } from "../pageObjects/POManager";
import { customtest as test, expect } from '../fixtures/testfixture';

test('@openaccount opens a checking account', async ({ page, testdataForregistration }) => {
    const pomanager = new POManager(page);
    const homepage = pomanager.getHomePage();
    const loginpage = pomanager.getLoginPage();
    const openAccountPage = pomanager.getOpenAccountPage();

    await homepage.goTo();
    await loginpage.clickToApplication(
        testdataForregistration.username,
        testdataForregistration.password
    );
    await expect(page).toHaveURL(/\\/overview\\.htm$/);

    await openAccountPage.clickOpenNewAccountLink();
    await expect(page).toHaveURL(/\\/openaccount\\.htm$/);
    await openAccountPage.openNewAccount('CHECKING');

    await expect(page.getByRole('heading', { name: 'Account Opened!' })).toBeVisible();
    await expect(page.getByText('Congratulations, your account is now open.')).toBeVisible();
    await expect(openAccountPage.openedAccountNumber).toBeVisible();
    await expect(openAccountPage.openedAccountNumber).toHaveText(/^\\d+$/);
});
`,
  'pageObjects/POManager.js': `import { HomePage } from "./HomePage";
import { RegistrationPage } from "./RegistrationPage";
import { LoginPage } from "./LoginPage";
import { OpenAccountPage } from "./OpenAccountPage";


export class POManager
{
    constructor(page)
    {
        this.page = page;
        this.homepage = new HomePage(this.page);
        this.registerPage = new RegistrationPage(this.page);
        this.loginPage = new LoginPage(this.page);
        this.openAccountPage = new OpenAccountPage(this.page);
    }
        getHomePage()
        {
            return this.homepage;
        }
        getRegistrationPage()
        {
            return this.registerPage;
        }
        getLoginPage()
        {
            return this.loginPage
        }
        getOpenAccountPage()
        {
            return this.openAccountPage;
        }
}
`
};
for (const [file, content] of Object.entries(files)) {
  fs.writeFileSync(path.join(process.cwd(), file), content, 'utf8');
}
let result;
try {
  result = spawnSync(process.execPath, [path.join('node_modules', '@playwright', 'test', 'cli.js'), 'test', 'tests/tcopenaccount.spec.js', '--list'], { stdio: 'inherit' });
  if (result.error) throw result.error;
  if (result.status !== 0) process.exitCode = result.status || 1;
} finally {
  const taskFile = path.join(process.cwd(), '.vscode', 'tasks.json');
  if (fs.existsSync(taskFile)) {
    const tasks = JSON.parse(fs.readFileSync(taskFile, 'utf8'));
    tasks.tasks = tasks.tasks.filter(task => task.label !== 'Update Open Account test');
    fs.writeFileSync(taskFile, JSON.stringify(tasks, null, 2) + '\n', 'utf8');
  }
}

